import{_ as i,o as n,c as a,a4 as l}from"./chunks/framework.B-wJupoK.js";const p="/assets/image-20250624233836836.BBBc5Xou.png",h="/assets/image-20250624234034040.DTviucBF.png",e="/assets/PixPin_2025-06-25_00-12-19.EpdW_5Be.gif",t="/assets/PixPin_2025-06-25_00-16-23.D4KN1afY.gif",k="/assets/PixPin_2025-06-25_00-22-41.C_IAwAN_.gif",r="/assets/image-20250622200325374.BLr7GNE1.png",F=JSON.parse(`{"title":"HarmonyOS 组件复用 @ReusableV2装饰器的基本使用","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用.md","filePath":"鸿蒙开发技巧/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用.md","lastUpdated":1751381397000,"__rawMarkdown":"# HarmonyOS 组件复用 @ReusableV2装饰器的基本使用\\n\\n## 介绍\\n\\n为了降低反复创建销毁自定义组件带来的性能开销，开发者可以使用@ReusableV2装饰@ComponentV2装饰的自定义组件，达成组\\n\\n件复用的效果。\\n\\n@ReusableV2用于装饰V2的自定义组件，表明该自定义组件具有被复用的能力。\\n\\n## 基本使用\\n\\n- @ReusableV2 用来装饰V2版本的自定义组件\\n- reuse是个属性方法，用来表示可以复用的组件的id，其中有多种使用的方式。\\n\\n\`\`\`typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  build() {\\n    Column() {\\n      ReusableV2Component()\\n        .reuse({reuseId: () => 'reuseComponent'}) // 使用'reuseComponent'作为reuseId\\n      ReusableV2Component()\\n        .reuse({reuseId: () => ''}) // 使用空字符串将默认使用组件名'ReusableV2Component'作为reuseId\\n      ReusableV2Component() // 未指定reuseId将默认使用组件名'ReusableV2Component'作为reuseId\\n    }\\n  }\\n}\\n@ReusableV2\\n@ComponentV2\\nstruct ReusableV2Component {\\n  build() {\\n  }\\n}\\n\`\`\`\\n\\n## 回收与复用的生命周期\\n\\n当组件被回收和被复用时，分别是\\n\\n- aboutToRecycle 回收\\n- aboutToReuse 复用\\n\\n另外，组件自身还具有创建和销毁，因此一个可以复用的组件是具有四个关键的生命周期的。\\n\\n|     生命周期     | 描述           |\\n| :--------------: | -------------- |\\n|  aboutToAppear   | **组件创建**   |\\n| aboutToDisappear | **组件销毁**   |\\n|  aboutToRecycle  | **组件被回收** |\\n|   aboutToReuse   | **组件复用**   |\\n\\n结合以下代码来理解\\n\\n\`\`\`typescript\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local condition1: boolean = false;\\n  @Local condition2: boolean = true;\\n\\n  build() {\\n    Column() {\\n      Button('step1. 组件创建')\\n        .onClick(() => {\\n          this.condition1 = true;\\n        })\\n      Button('step2. 组件回收')\\n        .onClick(() => {\\n          this.condition2 = false;\\n        })\\n      Button('step3. 组件重用')\\n        .onClick(() => {\\n          this.condition2 = true;\\n        })\\n      Button('step4. 组件销毁')\\n        .onClick(() => {\\n          this.condition1 = false;\\n        })\\n      if (this.condition1) {\\n        NormalV2Component({ condition: this.condition2 })\\n      }\\n    }\\n  }\\n}\\n\\n@ComponentV2\\nstruct NormalV2Component {\\n  @Require @Param condition: boolean;\\n\\n  build() {\\n    if (this.condition) {\\n      ReusableV2Component()\\n    }\\n  }\\n}\\n\\n@ReusableV2\\n@ComponentV2\\nstruct ReusableV2Component {\\n  aboutToAppear() {\\n    console.log('aboutToAppear'); // 组件创建时调用\\n  }\\n\\n  aboutToDisappear() {\\n    console.log('aboutToDisappear'); // 组件销毁时调用\\n  }\\n\\n  aboutToRecycle() {\\n    console.log('aboutToRecycle'); // 组件回收时调用\\n  }\\n\\n  aboutToReuse() {\\n    console.log('aboutToReuse'); // 组件复用时调用\\n  }\\n\\n  build() {\\n    Column() {\\n      Text('ReusableV2Component')\\n    }\\n  }\\n}\\n\`\`\`\\n\\n### 效果\\n\\n![image-20250624233836836](assets/image-20250624233836836.png)\\n\\n\\n\\n当我们依次点击按钮1、2、3、4时，控制台输出\\n\\n![image-20250624234034040](assets/image-20250624234034040.png)\\n\\n\\n\\n## 复用前的组件内状态变量重置\\n\\n这一个是个比较复杂和繁琐的知识点，该知识点重要讲解的是当组件被复用时，它身上使用不同装饰器修饰的变量是被重置，还是被保留下来。\\n\\n@ReusableV2在复用前会重置组件中的状态变量以及相关的@Computed、@Monitor的内容。在复用的过程当中，所有的V2自定义组件，无论是否被标记了@ReusableV2，都会经历这一个重置过程\\n\\n\\n\\n| 装饰器    | 重置方法                                                     |\\n| :-------- | :----------------------------------------------------------- |\\n| @Local    | 直接使用定义时的初始值重新赋值。                             |\\n| @Param    | 如果有外部传入则使用外部传入值重新赋值，否则用本地初始值重新赋值。注意：@Once装饰的变量同样会被重置初始化一次。 |\\n| @Event    | 如果有外部传入则使用外部传入值重新赋值，否则用本地初始值重新赋值。如果本地没有初始值，则生成默认的空实现。 |\\n| @Provider | 直接使用定义时的初始值重新赋值。                             |\\n| @Consumer | 如果有对应的@Provider则直接使用@Provider对应的值，否则使用本地初始值重新赋值。 |\\n| @Computed | 使用当前最新的值重新计算一次，如果使用到的变量还未被重置，将会使用重置前的值，因此推荐开发者将@Computed定义在所使用的变量之后。 |\\n| @Monitor  | 在上述所有变量重置完成之后触发。重置过程中产生的变量变化不会触发@Monitor回调，仅更新IMonitorValue中的before值。重置过程中不产生变化的赋值不会触发@Monitor的重置。 |\\n| 常量      | 包括readonly的常量，不重置。                                 |\\n\\n### @Local \\n\\n当组件被复用时，@Local被修饰的变量被重新赋值。\\n\\n\`\`\`typescript\\n@ComponentV2\\n@Entry\\nstruct Index {\\n  @Local isShow1: boolean = true\\n  build() {\\n    Column({ space: 10 }) {\\n      Button('复用/回收')\\n        .onClick(() => {\\n          this.isShow1 = !this.isShow1\\n        })\\n      if (this.isShow1) {\\n        Com()\\n      }\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n\\n\\n// 一个简单v2版本的组件\\n@ComponentV2\\n@ReusableV2\\nstruct Com {\\n  @Local num: number = 0\\n  aboutToReuse(): void {\\n    console.log(\\"复用\\")\\n  }\\n  aboutToRecycle(): void {\\n    console.log(\\"回收\\")\\n  }\\n  build() {\\n    Column() {\\n      Button('Com ' + this.num)\\n        .onClick(() => {\\n          this.num++\\n        })\\n\\n    }\\n  }\\n}\\n\`\`\`\\n\\n#### 效果\\n\\n![PixPin_2025-06-25_00-12-19](assets/PixPin_2025-06-25_00-12-19.gif)\\n\\n\\n\\n### @Param\\n\\n如果有外部传入则使用外部传入值重新赋值，否则用本地初始值重新赋值。注意：@Once装饰的变量同样会被重置初始化一次。\\n\\n\`\`\`typescript\\n@ComponentV2\\n@Entry\\nstruct Index {\\n  @Local isShow1: boolean = true\\n  @Local num: number = 0\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button('复用/回收')\\n        .onClick(() => {\\n          this.isShow1 = !this.isShow1\\n        })\\n\\n      Button(\\"+\\")\\n        .onClick(() => {\\n          this.num++\\n        })\\n      if (this.isShow1) {\\n        Com({ msg: this.num.toString() })\\n      }\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n\\n// 一个简单v2版本的组件\\n@ComponentV2\\n@ReusableV2\\nstruct Com {\\n  @Param msg: string = \\"\\"\\n\\n  aboutToReuse(): void {\\n    console.log(\\"复用\\")\\n  }\\n\\n  aboutToRecycle(): void {\\n    console.log(\\"回收\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button('Com ' + this.msg)\\n    }\\n  }\\n}\\n\\n\`\`\`\\n\\n#### 效果\\n\\n![PixPin_2025-06-25_00-16-23](assets/PixPin_2025-06-25_00-16-23.gif)\\n\\n### @Event\\n\\n如果有外部传入则使用外部传入值重新赋值，否则用本地初始值重新赋值。如果本地没有初始值，则生成默认的空实现。\\n\\n对于这个功能，没有什么特别的，正常理解即可。\\n\\n\`\`\`typescript\\n@ComponentV2\\n@Entry\\nstruct Index {\\n  @Local isShow1: boolean = true\\n  @Local num: number = 0\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button('复用/回收')\\n        .onClick(() => {\\n          this.isShow1 = !this.isShow1\\n        })\\n\\n      Button(\\"+\\")\\n        .onClick(() => {\\n          this.num++\\n        })\\n      if (this.isShow1) {\\n        Com({\\n          msg: this.num.toString(), cb: () => {\\n            this.num += 10\\n          }\\n        })\\n      }\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n\\n// 一个简单v2版本的组件\\n@ComponentV2\\n@ReusableV2\\nstruct Com {\\n  @Param msg: string = \\"\\"\\n  @Event cb: () => void = () => {\\n  }\\n\\n  aboutToReuse(): void {\\n    console.log(\\"复用\\")\\n  }\\n\\n  aboutToRecycle(): void {\\n    console.log(\\"回收\\")\\n  }\\n\\n  build() {\\n    Column() {\\n      Button('Com ' + this.msg)\\n        .onClick(() => {\\n          this.cb()\\n        })\\n    }\\n  }\\n}\\n\\n\`\`\`\\n\\n### @Provider\\n\\n直接使用定义时的初始值重新赋值。\\n\\n\`\`\`typescript\\n@ComponentV2\\n@Entry\\nstruct Index {\\n  @Local isShow1: boolean = true\\n  @Local num: number = 0\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button('复用/回收')\\n        .onClick(() => {\\n          this.isShow1 = !this.isShow1\\n        })\\n\\n      Button(\\"+\\")\\n        .onClick(() => {\\n          this.num++\\n        })\\n      if (this.isShow1) {\\n        Com()\\n      }\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n\\n// 一个简单v2版本的组件\\n@ComponentV2\\n@ReusableV2\\nstruct Com {\\n  @Provider(\\"msg\\") msg: string = \\"\\"\\n\\n  build() {\\n    Column() {\\n      Button('Com ' + this.msg)\\n        .onClick(() => {\\n          this.msg += \\"g\\"\\n        })\\n    }\\n  }\\n}\\n\\n\`\`\`\\n\\n#### 效果\\n\\n![PixPin_2025-06-25_00-22-41](assets/PixPin_2025-06-25_00-22-41.gif)\\n\\n### @Consumer\\n\\n如果有对应的@Provider则直接使用@Provider对应的值，否则使用本地初始值重新赋值。\\n\\n\`\`\`typescript\\n@ComponentV2\\n@Entry\\nstruct Index {\\n  @Local isShow1: boolean = true\\n  @Local num: number = 0\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button('复用/回收')\\n        .onClick(() => {\\n          this.isShow1 = !this.isShow1\\n        })\\n\\n      Button(\\"+\\")\\n        .onClick(() => {\\n          this.num++\\n        })\\n      if (this.isShow1) {\\n        Com()\\n      }\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n  }\\n}\\n\\n// 一个简单v2版本的组件\\n@ComponentV2\\n@ReusableV2\\nstruct Com {\\n  @Provider(\\"msg\\") msg: string = \\"\\"\\n\\n  @Computed\\n  get plusParam() {\\n    // msg 会被重置   aaa作为常量 不被重置\\n    return this.msg + \\" 666 \\" + this.aaa\\n  }\\n\\n  aaa = 10\\n\\n  build() {\\n    Column() {\\n      Button('Com ' + this.msg + \\"  \\" + this.plusParam)\\n        .onClick(() => {\\n          this.aaa += 100\\n          this.msg += \\"g\\"\\n        })\\n    }\\n  }\\n}\\n\\n\`\`\`\\n\\n### @Monitor\\n\\n在上述所有变量重置完成之后触发。重置过程中产生的变量变化不会触发@Monitor回调，仅更新IMonitorValue中的before值。重置过程中不产生变化的赋值不会触发@Monitor的重置。\\n\\n\\n\\n## 关于我们\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)\\n\\n"}`),E={name:"鸿蒙开发技巧/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用/HarmonyOS 组件复用 @ReusableV2装饰器的基本使用.md"};function d(g,s,c,y,b,o){return n(),a("div",null,[...s[0]||(s[0]=[l("",51)])])}const m=i(E,[["render",d]]);export{F as __pageData,m as default};
